arguments.content:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&family=Work+Sans:wght@300;400;500;600&display=swap');

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --blue: #0051C3;
  --blue-dark: #003D94;
  --blue-light: #E8F0FE;
  --red: #DE5052;
  --red-dark: #C43E40;
  --red-light: #FDEAEA;
  --white: #FFFFFF;
  --gray-50: #F8FAFC;
  --gray-100: #F1F5F9;
  --gray-200: #E2E8F0;
  --gray-300: #CBD5E1;
  --gray-400: #94A3B8;
  --gray-500: #64748B;
  --gray-600: #475569;
  --gray-700: #334155;
  --gray-800: #1E293B;
  --gray-900: #0F172A;
  --font-heading: 'Inter', system-ui, sans-serif;
  --font-body: 'Work Sans', system-ui, sans-serif;
  --max-width: 1200px;
  --transition: 200ms ease;
  --radius: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
  --shadow-lg: 0 10px 25px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.04);
  --shadow-xl: 0 20px 50px -5px rgba(0,0,0,0.1);
}

html { scroll-behavior: smooth; }
body {
  font-family: var(--font-body);
  color: var(--gray-800);
  line-height: 1.6;
  font-size: 16px;
  background: var(--white);
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.2;
  color: var(--gray-900);
}
h1 { font-size: 3.25rem; font-weight: 800; letter-spacing: -0.02em; }
h2 { font-size: 2.25rem; font-weight: 700; letter-spacing: -0.01em; }
h3 { font-size: 1.5rem; }
h4 { font-size: 1.25rem; }
p { color: var(--gray-600); line-height: 1.7; }
a { text-decoration: none; color: inherit; transition: color var(--transition); }
img { max-width: 100%; height: auto; }
ul { list-style: none; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* Buttons */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  padding: 14px 28px; border-radius: var(--radius); font-family: var(--font-heading);
  font-weight: 600; font-size: 1rem; cursor: pointer; border: none;
  transition: all var(--transition); white-space: nowrap;
}
.btn-primary {
  background: var(--blue); color: var(--white);
}
.btn-primary:hover { background: var(--blue-dark); transform: translateY(-1px); box-shadow: var(--shadow-lg); }
.btn-secondary {
  background: transparent; color: var(--blue); border: 2px solid var(--blue);
}
.btn-secondary:hover { background: var(--blue); color: var(--white); }
.btn-red { background: var(--red); color: var(--white); }
.btn-red:hover { background: var(--red-dark); transform: translateY(-1px); box-shadow: var(--shadow-lg); }
.btn-white { background: var(--white); color: var(--blue); }
.btn-white:hover { background: var(--gray-100); transform: translateY(-1px); }
.btn-lg { padding: 16px 36px; font-size: 1.1rem; border-radius: var(--radius-lg); }

/* Header */
.header {
  position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
  background: rgba(255,255,255,0.95); backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-200); transition: all 0.3s ease;
}
.header-inner {
  display: flex; align-items: center; justify-content: space-between;
  max-width: var(--max-width); margin: 0 auto; padding: 0 24px; height: 72px;
}
.logo {
  font-family: var(--font-heading); font-weight: 800; font-size: 1.5rem;
  color: var(--blue); display: flex; align-items: center; gap: 8px;
}
.logo svg { width: 32px; height: 32px; }
.nav-links { display: flex; align-items: center; gap: 32px; }
.nav-links a {
  font-family: var(--font-heading); font-weight: 500; font-size: 0.95rem;
  color: var(--gray-600); transition: color var(--transition);
}
.nav-links a:hover, .nav-links a.active { color: var(--blue); }
.nav-cta { margin-left: 8px; }
.hamburger {
  display: none; background: none; border: none; cursor: pointer; padding: 8px;
  width: 44px; height: 44px; align-items: center; justify-content: center;
}
.hamburger svg { width: 24px; height: 24px; stroke: var(--gray-700); }
.mobile-menu {
  display: none; position: fixed; top: 72px; left: 0; right: 0; bottom: 0;
  background: var(--white); z-index: 999; padding: 24px;
  flex-direction: column; gap: 8px;
  transform: translateX(100%); transition: transform 0.3s ease;
}
.mobile-menu.open { display: flex; transform: translateX(0); }
.mobile-menu a {
  display: block; padding: 16px; font-family: var(--font-heading); font-weight: 500;
  font-size: 1.1rem; color: var(--gray-700); border-radius: var(--radius);
  transition: background var(--transition);
}
.mobile-menu a:hover { background: var(--gray-50); color: var(--blue); }
.mobile-menu .btn { margin-top: 16px; text-align: center; }

/* Hero */
.hero {
  padding: 140px 0 80px; background: linear-gradient(135deg, var(--gray-50) 0%, var(--blue-light) 100%);
  position: relative; overflow: hidden;
}
.hero::before {
  content: ''; position: absolute; top: -50%; right: -20%; width: 600px; height: 600px;
  border-radius: 50%; background: rgba(0,81,195,0.04);
}
.hero .container { position: relative; z-index: 1; }
.hero-content { max-width: 720px; }
.hero-badge {
  display: inline-flex; align-items: center; gap: 8px; padding: 6px 16px;
  background: var(--white); border: 1px solid var(--gray-200); border-radius: 100px;
  font-size: 0.875rem; font-weight: 500; color: var(--blue); margin-bottom: 24px;
}
.hero-badge span { width: 8px; height: 8px; border-radius: 50%; background: var(--red); }
.hero h1 { margin-bottom: 20px; }
.hero p { font-size: 1.2rem; max-width: 600px; margin-bottom: 32px; }
.hero-buttons { display: flex; gap: 16px; flex-wrap: wrap; }

/* Section common */
.section { padding: 100px 0; }
.section-gray { background: var(--gray-50); }
.section-blue { background: var(--blue); color: var(--white); }
.section-blue h2, .section-blue h3, .section-blue h4 { color: var(--white); }
.section-blue p { color: rgba(255,255,255,0.85); }
.section-header { text-align: center; max-width: 640px; margin: 0 auto 60px; }
.section-header .label {
  display: inline-block; font-family: var(--font-heading); font-weight: 600;
  font-size: 0.875rem; text-transform: uppercase; letter-spacing: 0.08em;
  color: var(--blue); margin-bottom: 12px;
}
.section-header h2 { margin-bottom: 16px; }
.section-header p { font-size: 1.1rem; }

/* Features grid */
.features-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px;
}
.feature-card {
  padding: 32px; border-radius: var(--radius-xl); background: var(--white);
  border: 1px solid var(--gray-200); transition: all var(--transition);
}
.feature-card:hover { border-color: var(--blue); box-shadow: var(--shadow-lg); transform: translateY(-4px); }
.feature-icon {
  width: 56px; height: 56px; border-radius: var(--radius-lg); display: flex;
  align-items: center; justify-content: center; margin-bottom: 20px;
  background: var(--blue-light);
}
.feature-icon svg { width: 28px; height: 28px; stroke: var(--blue); fill: none; stroke-width: 1.5; }
.feature-card h3 { margin-bottom: 12px; font-size: 1.25rem; }
.feature-card p { font-size: 0.95rem; }

/* How it works */
.steps { display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px; counter-reset: step; }
.step { position: relative; text-align: center; padding: 24px; }
.step-number {
  width: 48px; height: 48px; border-radius: 50%; background: var(--blue);
  color: var(--white); display: flex; align-items: center; justify-content: center;
  font-family: var(--font-heading); font-weight: 700; font-size: 1.25rem;
  margin: 0 auto 20px;
}
.step h3 { margin-bottom: 12px; font-size: 1.1rem; }
.step p { font-size: 0.95rem; }
.step::after {
  content: ''; position: absolute; top: 48px; right: -16px; width: 32px; height: 2px;
  background: var(--gray-300);
}
.step:last-child::after { display: none; }

/* Stats */
.stats-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px; }
.stat-item { text-align: center; padding: 32px 16px; }
.stat-number {
  font-family: var(--font-heading); font-size: 3rem; font-weight: 800;
  color: var(--blue); margin-bottom: 8px; line-height: 1;
}
.section-blue .stat-number { color: var(--white); }
.stat-label { font-size: 1rem; font-weight: 500; color: var(--gray-500); }
.section-blue .stat-label { color: rgba(255,255,255,0.8); }

/* Testimonials */
.testimonial-carousel { position: relative; max-width: 800px; margin: 0 auto; overflow: hidden; }
.testimonial-track { display: flex; transition: transform 0.5s ease; }
.testimonial-slide { min-width: 100%; padding: 0 20px; }
.testimonial-card {
  background: var(--white); border-radius: var(--radius-xl); padding: 40px;
  border: 1px solid var(--gray-200); text-align: center;
}
.testimonial-stars { display: flex; justify-content: center; gap: 4px; margin-bottom: 20px; }
.testimonial-stars svg { width: 20px; height: 20px; fill: #FBBF24; }
.testimonial-card blockquote {
  font-size: 1.15rem; color: var(--gray-700); line-height: 1.7; margin-bottom: 24px;
  font-style: italic;
}
.testimonial-author { font-family: var(--font-heading); font-weight: 600; color: var(--gray-900); }
.testimonial-role { font-size: 0.9rem; color: var(--gray-500); margin-top: 4px; }
.carousel-controls { display: flex; justify-content: center; gap: 12px; margin-top: 32px; }
.carousel-btn {
  width: 48px; height: 48px; border-radius: 50%; border: 2px solid var(--gray-300);
  background: var(--white); cursor: pointer; display: flex; align-items: center;
  justify-content: center; transition: all var(--transition);
}
.carousel-btn:hover { border-color: var(--blue); background: var(--blue-light); }
.carousel-btn svg { width: 20px; height: 20px; stroke: var(--gray-600); }
.carousel-dots { display: flex; justify-content: center; gap: 8px; margin-top: 20px; }
.carousel-dot {
  width: 10px; height: 10px; border-radius: 50%; background: var(--gray-300);
  border: none; cursor: pointer; transition: all var(--transition); padding: 0;
}
.carousel-dot.active { background: var(--blue); width: 28px; border-radius: 5px; }

/* Pricing teaser */
.pricing-teaser-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.pricing-teaser-card {
  padding: 32px; border-radius: var(--radius-xl); background: var(--white);
  border: 1px solid var(--gray-200); text-align: center;
  transition: all var(--transition);
}
.pricing-teaser-card.featured {
  border-color: var(--blue); position: relative; box-shadow: var(--shadow-lg);
}
.pricing-teaser-card.featured::before {
  content: 'Most Popular'; position: absolute; top: -14px; left: 50%; transform: translateX(-50%);
  background: var(--blue); color: var(--white); padding: 4px 16px; border-radius: 100px;
  font-family: var(--font-heading); font-size: 0.8rem; font-weight: 600;
}
.pricing-teaser-card h3 { margin-bottom: 8px; }
.pricing-teaser-price {
  font-family: var(--font-heading); font-size: 2.5rem; font-weight: 800;
  color: var(--gray-900); margin: 16px 0;
}
.pricing-teaser-price span { font-size: 1rem; font-weight: 400; color: var(--gray-500); }
.pricing-teaser-card p { font-size: 0.95rem; margin-bottom: 24px; }

/* CTA section */
.cta-section {
  padding: 80px 0; background: linear-gradient(135deg, var(--blue) 0%, var(--blue-dark) 100%);
  text-align: center; color: var(--white);
}
.cta-section h2 { color: var(--white); margin-bottom: 16px; }
.cta-section p { color: rgba(255,255,255,0.85); font-size: 1.15rem; max-width: 580px; margin: 0 auto 32px; }
.cta-buttons { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

/* Footer */
.footer { background: var(--gray-900); color: var(--gray-400); padding: 64px 0 32px; }
.footer-grid {
  display: grid; grid-template-columns: 2fr repeat(4, 1fr); gap: 40px; margin-bottom: 48px;
}
.footer-brand .logo { color: var(--white); margin-bottom: 16px; }
.footer-brand p { font-size: 0.9rem; line-height: 1.7; color: var(--gray-400); }
.footer-col h4 {
  font-size: 0.875rem; text-transform: uppercase; letter-spacing: 0.08em;
  color: var(--gray-300); margin-bottom: 16px;
}
.footer-col a {
  display: block; padding: 4px 0; font-size: 0.9rem; color: var(--gray-400);
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--white); }
.footer-bottom {
  border-top: 1px solid var(--gray-700); padding-top: 24px;
  display: flex; justify-content: space-between; align-items: center;
  font-size: 0.85rem;
}
.footer-socials { display: flex; gap: 16px; }
.footer-socials a { color: var(--gray-400); transition: color var(--transition); }
.footer-socials a:hover { color: var(--white); }
.footer-socials svg { width: 20px; height: 20px; }

/* Pricing page */
.billing-toggle {
  display: flex; align-items: center; justify-content: center; gap: 16px; margin-bottom: 48px;
}
.billing-toggle span { font-weight: 500; color: var(--gray-500); }
.billing-toggle span.active { color: var(--gray-900); }
.toggle-switch {
  width: 56px; height: 30px; border-radius: 15px; background: var(--gray-300);
  cursor: pointer; position: relative; border: none; transition: background var(--transition);
}
.toggle-switch.active { background: var(--blue); }
.toggle-switch::after {
  content: ''; position: absolute; top: 3px; left: 3px; width: 24px; height: 24px;
  border-radius: 50%; background: var(--white); transition: transform var(--transition);
  box-shadow: var(--shadow-sm);
}
.toggle-switch.active::after { transform: translateX(26px); }
.save-badge {
  background: var(--red-light); color: var(--red); padding: 4px 12px;
  border-radius: 100px; font-size: 0.8rem; font-weight: 600;
}

.pricing-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.pricing-card {
  border-radius: var(--radius-xl); background: var(--white); padding: 40px;
  border: 1px solid var(--gray-200); transition: all var(--transition);
  display: flex; flex-direction: column;
}
.pricing-card.featured {
  border-color: var(--blue); box-shadow: var(--shadow-xl); position: relative;
  transform: scale(1.03);
}
.pricing-card.featured::before {
  content: 'Most Popular'; position: absolute; top: -14px; left: 50%; transform: translateX(-50%);
  background: var(--blue); color: var(--white); padding: 4px 20px; border-radius: 100px;
  font-family: var(--font-heading); font-size: 0.8rem; font-weight: 600;
}
.pricing-card h3 { margin-bottom: 4px; font-size: 1.35rem; }
.pricing-card .price-desc { font-size: 0.9rem; color: var(--gray-500); margin-bottom: 20px; }
.price-amount {
  font-family: var(--font-heading); font-size: 3rem; font-weight: 800;
  color: var(--gray-900); line-height: 1;
}
.price-amount .currency { font-size: 1.5rem; vertical-align: super; }
.price-amount .period { font-size: 1rem; font-weight: 400; color: var(--gray-500); }
.price-row { margin: 24px 0; padding: 20px 0; border-top: 1px solid var(--gray-200); }
.pricing-features { flex: 1; margin-bottom: 32px; }
.pricing-features li {
  display: flex; align-items: flex-start; gap: 12px; padding: 8px 0;
  font-size: 0.95rem; color: var(--gray-600);
}
.pricing-features li svg { width: 20px; height: 20px; flex-shrink: 0; margin-top: 2px; }
.pricing-features li svg.check { stroke: #16A34A; }
.pricing-features li svg.x { stroke: var(--gray-400); }
.pricing-features li.disabled { color: var(--gray-400); }
.pricing-card .btn { width: 100%; }

/* FAQ */
.faq-list { max-width: 760px; margin: 0 auto; }
.faq-item {
  border-bottom: 1px solid var(--gray-200); overflow: hidden;
}
.faq-question {
  width: 100%; padding: 20px 0; background: none; border: none; cursor: pointer;
  display: flex; justify-content: space-between; align-items: center; gap: 16px;
  font-family: var(--font-heading); font-weight: 600; font-size: 1.05rem;
  color: var(--gray-800); text-align: left;
}
.faq-question:hover { color: var(--blue); }
.faq-question svg {
  width: 20px; height: 20px; stroke: var(--gray-400); flex-shrink: 0;
  transition: transform 0.3s ease;
}
.faq-item.open .faq-question svg { transform: rotate(180deg); }
.faq-answer {
  max-height: 0; overflow: hidden; transition: max-height 0.3s ease, padding 0.3s ease;
}
.faq-answer p { padding-bottom: 20px; font-size: 0.95rem; }
.faq-item.open .faq-answer { max-height: 200px; }

/* Feature detail (features page) */
.feature-detail {
  display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center;
  padding: 60px 0;
}
.feature-detail:nth-child(even) { direction: rtl; }
.feature-detail:nth-child(even) > * { direction: ltr; }
.feature-detail-content .label {
  display: inline-block; font-family: var(--font-heading); font-weight: 600;
  font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.08em;
  color: var(--blue); margin-bottom: 12px;
}
.feature-detail-content h2 { font-size: 2rem; margin-bottom: 16px; }
.feature-detail-content p { margin-bottom: 24px; }
.feature-detail-content ul { margin-bottom: 24px; }
.feature-detail-content li {
  display: flex; align-items: flex-start; gap: 12px; padding: 8px 0;
  font-size: 0.95rem; color: var(--gray-600);
}
.feature-detail-content li svg {
  width: 20px; height: 20px; stroke: #16A34A; flex-shrink: 0; margin-top: 2px;
}
.feature-visual {
  background: var(--gray-50); border-radius: var(--radius-xl);
  padding: 40px; min-height: 340px; display: flex; align-items: center;
  justify-content: center; border: 1px solid var(--gray-200);
}
.feature-visual-inner {
  width: 100%; text-align: center;
}
.feature-visual svg { max-width: 280px; width: 100%; height: auto; }

/* Integration grid */
.integration-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
.integration-card {
  padding: 28px; background: var(--white); border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg); text-align: center;
  transition: all var(--transition);
}
.integration-card:hover { border-color: var(--blue); box-shadow: var(--shadow); transform: translateY(-2px); }
.integration-card h4 { margin-bottom: 12px; color: var(--blue); }
.integration-card p { font-size: 0.9rem; }

/* About page */
.mission-content { display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center; }
.mission-content p { font-size: 1.1rem; margin-bottom: 16px; }
.mission-visual {
  background: linear-gradient(135deg, var(--blue-light), var(--gray-50));
  border-radius: var(--radius-xl); min-height: 360px;
  display: flex; align-items: center; justify-content: center;
}
.team-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px; }
.team-card { text-align: center; }
.team-avatar {
  width: 120px; height: 120px; border-radius: 50%; margin: 0 auto 16px;
  display: flex; align-items: center; justify-content: center;
  font-family: var(--font-heading); font-weight: 700; font-size: 2rem; color: var(--white);
}
.team-card:nth-child(1) .team-avatar { background: var(--blue); }
.team-card:nth-child(2) .team-avatar { background: var(--red); }
.team-card:nth-child(3) .team-avatar { background: #7C3AED; }
.team-card:nth-child(4) .team-avatar { background: #059669; }
.team-card h3 { font-size: 1.15rem; margin-bottom: 4px; }
.team-card p { font-size: 0.9rem; color: var(--gray-500); }

/* Contact page */
.contact-layout { display: grid; grid-template-columns: 1fr 1fr; gap: 60px; }
.contact-form-wrapper {
  background: var(--white); border-radius: var(--radius-xl); padding: 40px;
  border: 1px solid var(--gray-200); box-shadow: var(--shadow-lg);
}
.form-group { margin-bottom: 20px; }
.form-group label {
  display: block; font-family: var(--font-heading); font-weight: 500;
  font-size: 0.9rem; color: var(--gray-700); margin-bottom: 6px;
}
.form-group label .required { color: var(--red); }
.form-group input, .form-group select, .form-group textarea {
  width: 100%; padding: 12px 16px; border: 1px solid var(--gray-300);
  border-radius: var(--radius); font-family: var(--font-body); font-size: 1rem;
  color: var(--gray-800); transition: border-color var(--transition);
  background: var(--white);
}
.form-group input:focus, .form-group select:focus, .form-group textarea:focus {
  outline: none; border-color: var(--blue); box-shadow: 0 0 0 3px rgba(0,81,195,0.1);
}
.form-group textarea { resize: vertical; min-height: 120px; }
.form-group .error-msg {
  display: none; font-size: 0.85rem; color: var(--red); margin-top: 4px;
}
.form-group.error input, .form-group.error textarea, .form-group.error select {
  border-color: var(--red);
}
.form-group.error .error-msg { display: block; }
.form-success {
  display: none; text-align: center; padding: 40px;
}
.form-success svg { width: 56px; height: 56px; stroke: #16A34A; margin-bottom: 16px; }
.form-success h3 { margin-bottom: 8px; }

.contact-info { padding: 20px 0; }
.contact-info h3 { margin-bottom: 24px; }
.contact-info-item { display: flex; gap: 16px; margin-bottom: 24px; }
.contact-info-icon {
  width: 48px; height: 48px; border-radius: var(--radius-lg); background: var(--blue-light);
  display: flex; align-items: center; justify-content: center; flex-shrink: 0;
}
